use xiom.io;

enum Size {
  Small,
  Medium,
  Large,
}

type MenuItem = {
  name: Str;
  price: Float64;
  size: Size;
}

fn format_price(item: MenuItem) -> Str {
  return item.name + " - $" + item.price + " (" + item.size + ")";
}

fn upsize(item: MenuItem) -> MenuItem {
  var new_size = item.size;
  if item.size == Size.Small {
    new_size = Size.Medium;
  }
  if item.size == Size.Medium {
    new_size = Size.Large;
  }
  return MenuItem{
    name: item.name;
    price: item.price * 1.3;
    size: new_size;
  };
}

fn main() -> Int {
  let latte = MenuItem{ name: "Latte"; price: 4.50; size: Size.Medium; };
  let large_latte = upsize(latte);
  return (large_latte.price * 100.0) as Int;
}
